package approval

import "github.com/TrebuchetDynamics/gormes-agent/internal/tools/safety"

type PatternMatch struct {
	Pattern     string
	Description string
}

type CheckResult struct {
	Approved    bool   `json:"approved"`
	Hardline    bool   `json:"hardline,omitempty"`
	Dangerous   bool   `json:"dangerous,omitempty"`
	Description string `json:"description,omitempty"`
	Message     string `json:"message,omitempty"`
}

func hardlineBlockResult(desc string) CheckResult {
	return CheckResult{
		Approved:    false,
		Hardline:    true,
		Description: desc,
		Message: "BLOCKED (hardline): " + desc + ". This command is on the unconditional " +
			"blocklist and cannot be executed via the agent — not even with --yolo, " +
			"/yolo, approvals.mode=off, or cron approve mode.",
	}
}

func CheckHardline(command string) CheckResult {
	if match, desc := safety.DetectHardline(command); match {
		return hardlineBlockResult(desc)
	}
	return CheckResult{Approved: true}
}

func CheckDangerous(command string) (bool, string) {
	return safety.DetectDangerous(command)
}

func CheckAll(command string) CheckResult {
	if result := CheckHardline(command); !result.Approved {
		return result
	}
	if match, desc := CheckDangerous(command); match {
		return CheckResult{
			Approved:    false,
			Dangerous:   true,
			Description: desc,
			Message:     "This command matched dangerous pattern: " + desc + ". Approval required.",
		}
	}
	return CheckResult{Approved: true}
}

package approval

import (
	"context"

	"github.com/TrebuchetDynamics/gormes-agent/internal/tools/safety"
)

// ApprovalRequest describes a dangerous operation that needs an explicit
// operator approval decision before a worker may continue.
type ApprovalRequest struct {
	ToolName    string
	Command     string
	Mode        string
	Description string
	Evidence    map[string]string
}

// ApprovalDecision is the callback's bounded decision. Approved=false denies.
type ApprovalDecision struct {
	Approved bool
	Reason   string
	Evidence map[string]string
}

// ApprovalCallback is injected by an interactive parent when a concurrent
// worker is allowed to ask the same explicit approval policy. Absence means
// noninteractive fail-closed; callers must not fall back to stdin.
type ApprovalCallback func(context.Context, ApprovalRequest) (ApprovalDecision, error)

type approvalCallbackContextKey struct{}

// WithApprovalCallback returns a child context carrying cb. Passing nil leaves
// ctx unchanged so callback cleanup is just normal context scoping.
func WithApprovalCallback(ctx context.Context, cb ApprovalCallback) context.Context {
	if ctx == nil {
		ctx = context.Background()
	}
	if cb == nil {
		return ctx
	}
	return context.WithValue(ctx, approvalCallbackContextKey{}, cb)
}

// ApprovalCallbackFromContext returns the explicitly injected approval callback.
func ApprovalCallbackFromContext(ctx context.Context) (ApprovalCallback, bool) {
	if ctx == nil {
		return nil, false
	}
	cb, ok := ctx.Value(approvalCallbackContextKey{}).(ApprovalCallback)
	return cb, ok && cb != nil
}

// GuardCommandWithApproval applies GuardCommand and, for recoverable dangerous
// commands only, consults an explicit context callback. Missing callbacks and
// callback failures deny without interactive stdin fallback.
func GuardCommandWithApproval(ctx context.Context, toolName, cmd, mode string) safety.BlockedResult {
	approvalMode := NormalizeApprovalMode(mode)
	result := safety.GuardCommand(cmd, approvalMode.Mode)
	if result.Description == "" || result.Approved || result.Hardline || !result.ApprovalRequired {
		return result
	}
	cb, ok := ApprovalCallbackFromContext(ctx)
	if !ok {
		return approvalCallbackDenied(result, "approval_callback_missing", "")
	}
	decision, err := cb(ctx, ApprovalRequest{
		ToolName:    toolName,
		Command:     cmd,
		Mode:        result.Operator,
		Description: result.Description,
		Evidence:    cloneStringMap(result.Evidence),
	})
	if err != nil {
		return approvalCallbackDenied(result, "approval_callback_error", err.Error())
	}
	if !decision.Approved {
		reason := decision.Reason
		if reason == "" {
			reason = "approval_callback_denied"
		}
		denied := approvalCallbackDenied(result, reason, "")
		for k, v := range decision.Evidence {
			denied.Evidence[k] = v
		}
		return denied
	}
	result.Approved = true
	result.ApprovalRequired = false
	result.Evidence["approval_callback"] = "approved"
	for k, v := range decision.Evidence {
		result.Evidence[k] = v
	}
	return result
}

func approvalCallbackDenied(result safety.BlockedResult, reason, errText string) safety.BlockedResult {
	result.Approved = false
	result.ApprovalRequired = true
	if result.Evidence == nil {
		result.Evidence = map[string]string{}
	}
	result.Evidence["reason"] = reason
	result.Evidence["approval_callback"] = "denied"
	if errText != "" {
		result.Evidence["error"] = errText
	}
	return result
}

func cloneStringMap(in map[string]string) map[string]string {
	if in == nil {
		return nil
	}
	out := make(map[string]string, len(in))
	for k, v := range in {
		out[k] = v
	}
	return out
}

package approval

import (
	"context"
	"strings"
)

const (
	ApprovalModeManual = "manual"
	ApprovalModeSmart  = "smart"
	ApprovalModeOff    = "off"

	CronApprovalModeDeny    = "deny"
	CronApprovalModeApprove = "approve"
)

// ApprovalMode describes a normalized dangerous-command approval mode plus
// redacted evidence about whether the value had to fall back to the safe
// manual default.
type ApprovalMode struct {
	Mode      string
	Defaulted bool
	Evidence  map[string]string
}

type cronApprovalModeContextKey struct{}

// WithCronApprovalMode marks a tool execution context as a noninteractive
// cron turn governed by approvals.cron_mode instead of the interactive
// terminal approval path.
func WithCronApprovalMode(ctx context.Context, value any) context.Context {
	if ctx == nil {
		ctx = context.Background()
	}
	mode := NormalizeCronApprovalMode(value)
	return context.WithValue(ctx, cronApprovalModeContextKey{}, mode.Mode)
}

// CronApprovalModeFromContext returns the normalized cron approval mode when
// the caller explicitly scoped this tool execution to a cron turn.
func CronApprovalModeFromContext(ctx context.Context) (string, bool) {
	if ctx == nil {
		return "", false
	}
	raw, ok := ctx.Value(cronApprovalModeContextKey{}).(string)
	if !ok {
		return "", false
	}
	return NormalizeCronApprovalMode(raw).Mode, true
}

// NormalizeApprovalMode ports Hermes' approval mode parsing semantics for
// config-loaded values. YAML 1.1 parses bare `off` as boolean false, so false
// must mean the operator intended approval mode "off" rather than defaulting
// to manual.
func NormalizeApprovalMode(value any) ApprovalMode {
	mode := ApprovalMode{Mode: ApprovalModeManual, Evidence: map[string]string{"approval_mode": ApprovalModeManual}}
	switch v := value.(type) {
	case bool:
		if !v {
			mode.Mode = ApprovalModeOff
			mode.Evidence["approval_mode"] = ApprovalModeOff
		}
		return mode
	case string:
		normalized := strings.ToLower(strings.TrimSpace(v))
		switch normalized {
		case ApprovalModeManual, ApprovalModeSmart, ApprovalModeOff:
			mode.Mode = normalized
			mode.Evidence["approval_mode"] = normalized
			return mode
		}
	}
	mode.Defaulted = true
	mode.Evidence["approval_mode_defaulted"] = "true"
	return mode
}

// NormalizeCronApprovalMode ports Hermes' approvals.cron_mode parser. Cron is
// non-interactive, so unsupported values fail closed to deny; only explicit
// approve aliases opt into recoverable dangerous-command auto-approval.
func NormalizeCronApprovalMode(value any) ApprovalMode {
	mode := ApprovalMode{Mode: CronApprovalModeDeny, Evidence: map[string]string{"cron_approval_mode": CronApprovalModeDeny}}
	raw, ok := value.(string)
	if !ok {
		mode.Defaulted = true
		mode.Evidence["cron_approval_mode_defaulted"] = "true"
		return mode
	}
	switch strings.ToLower(strings.TrimSpace(raw)) {
	case CronApprovalModeApprove, ApprovalModeOff, "allow", "yes":
		mode.Mode = CronApprovalModeApprove
		mode.Evidence["cron_approval_mode"] = CronApprovalModeApprove
		return mode
	case CronApprovalModeDeny:
		return mode
	default:
		mode.Defaulted = true
		mode.Evidence["cron_approval_mode_defaulted"] = "true"
		return mode
	}
}

package approval

import (
	"fmt"
	"strings"
	"sync"
	"time"

	"github.com/TrebuchetDynamics/gormes-agent/internal/tools/safety"
)

type UXDecision string

const (
	UXDecisionYes     UXDecision = "yes"
	UXDecisionNo      UXDecision = "no"
	UXDecisionAlways  UXDecision = "always"
	UXDecisionUnknown UXDecision = "unknown"
)

type ApprovalPrompt struct {
	Command       string
	Category      safety.BlocklistCategory
	AffectedPaths []string
	RiskLevel     string
}

type ApprovalUXResult struct {
	Decision    UXDecision
	Persisted   bool
	Evidence    string
	AuditRecord ApprovalAuditRecord
}

type ApprovalAuditRecord struct {
	Timestamp time.Time
	Command   string
	Category  string
	Decision  string
	Context   string
}

type ApprovalSession struct {
	mu          sync.RWMutex
	preferences map[string]UXDecision
	interactive bool
	auditLog    []ApprovalAuditRecord
}

func NewApprovalSession(interactive bool) *ApprovalSession {
	return &ApprovalSession{
		preferences: make(map[string]UXDecision),
		interactive: interactive,
		auditLog:    make([]ApprovalAuditRecord, 0),
	}
}

func (s *ApprovalSession) RequestApproval(prompt ApprovalPrompt, onPrompt func(ApprovalPrompt) UXDecision) ApprovalUXResult {
	if !s.interactive {
		return ApprovalUXResult{
			Decision: UXDecisionNo,
			Evidence: "approval_ui_unavailable: non-interactive context",
			AuditRecord: ApprovalAuditRecord{
				Timestamp: time.Now(),
				Command:   prompt.Command,
				Category:  string(prompt.Category),
				Decision:  "denied",
				Context:   "non-interactive",
			},
		}
	}

	s.mu.RLock()
	pref, hasPref := s.preferences[string(prompt.Category)]
	s.mu.RUnlock()

	if hasPref {
		return ApprovalUXResult{
			Decision:  pref,
			Persisted: true,
			Evidence:  fmt.Sprintf("approval_preference_applied: %s for category %s", pref, prompt.Category),
			AuditRecord: ApprovalAuditRecord{
				Timestamp: time.Now(),
				Command:   prompt.Command,
				Category:  string(prompt.Category),
				Decision:  string(pref),
				Context:   "preference",
			},
		}
	}

	decision := onPrompt(prompt)

	result := ApprovalUXResult{
		Decision: decision,
		Evidence: fmt.Sprintf("approval_prompt_decision: %s", decision),
		AuditRecord: ApprovalAuditRecord{
			Timestamp: time.Now(),
			Command:   prompt.Command,
			Category:  string(prompt.Category),
			Decision:  string(decision),
			Context:   "interactive",
		},
	}

	if decision == UXDecisionAlways {
		s.mu.Lock()
		s.preferences[string(prompt.Category)] = UXDecisionYes
		s.mu.Unlock()
		result.Persisted = true
		result.Decision = UXDecisionYes
		result.Evidence = fmt.Sprintf("approval_always_persisted: category %s", prompt.Category)
	}

	s.mu.Lock()
	s.auditLog = append(s.auditLog, result.AuditRecord)
	s.mu.Unlock()

	return result
}

func (s *ApprovalSession) GetPreferenceCount() int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return len(s.preferences)
}

func (s *ApprovalSession) GetAuditLog() []ApprovalAuditRecord {
	s.mu.RLock()
	defer s.mu.RUnlock()
	log := make([]ApprovalAuditRecord, len(s.auditLog))
	copy(log, s.auditLog)
	return log
}

func (s *ApprovalSession) IsInteractive() bool {
	return s.interactive
}

func BuildApprovalPrompt(command string, category safety.BlocklistCategory) ApprovalPrompt {
	riskLevel := "medium"
	switch category {
	case safety.BlocklistDestructive:
		riskLevel = "high"
	case safety.BlocklistPrivilege:
		riskLevel = "high"
	case safety.BlocklistDataExfil:
		riskLevel = "high"
	case safety.BlocklistNetwork:
		riskLevel = "medium"
	case safety.BlocklistCryptoMine:
		riskLevel = "medium"
	}

	return ApprovalPrompt{
		Command:       command,
		Category:      category,
		AffectedPaths: extractPaths(command),
		RiskLevel:     riskLevel,
	}
}

func extractPaths(command string) []string {
	var paths []string
	words := strings.Fields(command)
	for _, w := range words {
		if strings.HasPrefix(w, "/") || strings.HasPrefix(w, "./") || strings.HasPrefix(w, "../") {
			paths = append(paths, w)
		}
	}
	return paths
}

