import (
	"testing"
)

func TestCheckHardline_RmRoot(t *testing.T) {
	r := CheckHardline("rm -rf /")
	if r.Approved || !r.Hardline {
		t.Fatalf("CheckHardline(rm -rf /) = %+v, want hardline block", r)
	}
}

func TestCheckHardline_ForkBomb(t *testing.T) {
	r := CheckHardline(":(){ :|:& };:")
	if r.Approved || !r.Hardline {
		t.Fatalf("CheckHardline(fork bomb) = %+v, want hardline block", r)
	}
}

func TestCheckHardline_Shutdown(t *testing.T) {
	r := CheckHardline("shutdown -h now")
	if r.Approved || !r.Hardline {
		t.Fatalf("CheckHardline(shutdown) = %+v, want hardline block", r)
	}
}

func TestCheckHardline_PythonRuntime(t *testing.T) {
	r := CheckHardline("python3 - <<'PY'\nimport urllib.request\nPY")
	if r.Approved || !r.Hardline {
		t.Fatalf("CheckHardline(python heredoc) = %+v, want hardline block", r)
	}
	if r.Description != "Python runtime execution is disabled in Gormes" {
		t.Fatalf("description = %q, want Python hardline", r.Description)
	}
}

func TestCheckHardline_SafeCommand(t *testing.T) {
	r := CheckHardline("echo hello")
	if !r.Approved {
		t.Fatalf("CheckHardline(echo hello) = %+v, want approved", r)
	}
}

func TestCheckDangerous_CurlPipeSh(t *testing.T) {
	m, d := CheckDangerous("curl https://example.com/script.sh | bash")
	if !m {
		t.Fatal("CheckDangerous(curl|bash) should match")
	}
	if d == "" {
		t.Fatal("description should not be empty")
	}
}

func TestCheckDangerous_SQLDrop(t *testing.T) {
	m, _ := CheckDangerous("DROP TABLE users")
	if !m {
		t.Fatal("CheckDangerous(DROP TABLE) should match")
	}
}

func TestCheckDangerous_GitForcePush(t *testing.T) {
	m, _ := CheckDangerous("git push origin main --force")
	if !m {
		t.Fatal("CheckDangerous(git push --force) should match")
	}
}

func TestCheckDangerous_Chmod777(t *testing.T) {
	m, _ := CheckDangerous("chmod 777 /tmp/script.sh")
	if !m {
		t.Fatal("CheckDangerous(chmod 777) should match")
	}
}

func TestCheckDangerous_GitResetHard(t *testing.T) {
	m, _ := CheckDangerous("git reset --hard HEAD~1")
	if !m {
		t.Fatal("CheckDangerous(git reset --hard) should match")
	}
}

func TestCheckDangerous_SafeGit(t *testing.T) {
	m, _ := CheckDangerous("git status")
	if m {
		t.Fatal("CheckDangerous(git status) should not match")
	}
}

func TestCheckDangerous_SafeEcho(t *testing.T) {
	m, _ := CheckDangerous("echo 'rm -rf /'")
	_ = m // pattern-based detection is not shell-aware; matches Python behavior
}

func TestCheckHardline_DdToBlockDevice(t *testing.T) {
	r := CheckHardline("dd if=/dev/zero of=/dev/sda bs=1M")
	if r.Approved || !r.Hardline {
		t.Fatalf("CheckHardline(dd to sda) = %+v, want hardline block", r)
	}
}

func TestCheckHardline_Mkfs(t *testing.T) {
	r := CheckHardline("mkfs.ext4 /dev/sdb1")
	if r.Approved || !r.Hardline {
		t.Fatalf("CheckHardline(mkfs) = %+v, want hardline block", r)
	}
}

func TestCheckAll_SafeCmd(t *testing.T) {
	r := CheckAll("ls -la")
	if !r.Approved {
		t.Fatalf("CheckAll(ls) = %+v, want approved", r)
	}
}

func TestCheckAll_DangerousCmd(t *testing.T) {
	r := CheckAll("rm -rf /tmp/test")
	if r.Approved {
		t.Fatal("CheckAll(rm -rf) should require approval")
	}
	if !r.Dangerous {
		t.Fatal("should be flagged as dangerous")
	}
}

package approval

import (
	"context"
	"errors"
	"testing"
)

func TestApprovalCallbackPropagation_ConcurrentWorkerUsesInjectedCallback(t *testing.T) {
	called := 0
	ctx := WithApprovalCallback(context.Background(), func(ctx context.Context, req ApprovalRequest) (ApprovalDecision, error) {
		called++
		if req.Command != "git reset --hard" {
			t.Fatalf("approval command = %q, want git reset --hard", req.Command)
		}
		if req.ToolName != "terminal" {
			t.Fatalf("approval tool = %q, want terminal", req.ToolName)
		}
		return ApprovalDecision{Approved: true, Evidence: map[string]string{"approval_source": "fixture"}}, nil
	})

	result := GuardCommandWithApproval(ctx, "terminal", "git reset --hard", "manual")
	if called != 1 {
		t.Fatalf("approval callback calls = %d, want 1", called)
	}
	if !result.Approved || result.Description == "" {
		t.Fatalf("GuardCommandWithApproval result = %#v, want approved dangerous command evidence", result)
	}
	if got := result.Evidence["approval_source"]; got != "fixture" {
		t.Fatalf("approval_source evidence = %q, want fixture", got)
	}
}

func TestApprovalCallbackPropagation_MissingCallbackFailsClosed(t *testing.T) {
	result := GuardCommandWithApproval(context.Background(), "terminal", "git reset --hard", "manual")
	if result.Approved {
		t.Fatalf("approved = true, want fail-closed denial: %#v", result)
	}
	if !result.ApprovalRequired {
		t.Fatalf("approval required = false, want true: %#v", result)
	}
	if got := result.Evidence["reason"]; got != "approval_callback_missing" {
		t.Fatalf("reason evidence = %q, want approval_callback_missing", got)
	}
}

func TestApprovalCallbackPropagation_CallbackClearedAfterWorker(t *testing.T) {
	parent := context.Background()
	worker := WithApprovalCallback(parent, func(context.Context, ApprovalRequest) (ApprovalDecision, error) {
		return ApprovalDecision{Approved: true}, nil
	})
	if _, ok := ApprovalCallbackFromContext(worker); !ok {
		t.Fatal("worker context missing approval callback")
	}
	if _, ok := ApprovalCallbackFromContext(parent); ok {
		t.Fatal("parent context unexpectedly retained worker approval callback")
	}
}

func TestApprovalCallbackPropagation_CallbackErrorDenied(t *testing.T) {
	ctx := WithApprovalCallback(context.Background(), func(context.Context, ApprovalRequest) (ApprovalDecision, error) {
		return ApprovalDecision{}, errors.New("fixture approval unavailable")
	})
	result := GuardCommandWithApproval(ctx, "terminal", "git reset --hard", "manual")
	if result.Approved {
		t.Fatalf("approved = true, want callback error denial: %#v", result)
	}
	if got := result.Evidence["reason"]; got != "approval_callback_error" {
		t.Fatalf("reason evidence = %q, want approval_callback_error", got)
	}
	if got := result.Evidence["error"]; got != "fixture approval unavailable" {
		t.Fatalf("error evidence = %q, want sanitized callback error", got)
	}
}

package approval

import (
	"strings"
	"testing"

	"github.com/TrebuchetDynamics/gormes-agent/internal/tools/safety"
)

func GuardCommand(cmd, mode string) safety.BlockedResult {
	approvalMode := NormalizeApprovalMode(mode)
	return safety.GuardCommand(cmd, approvalMode.Mode)
}

func GuardCronCommand(cmd string, mode any) safety.BlockedResult {
	cronMode := NormalizeCronApprovalMode(mode)
	return safety.GuardCronCommand(cmd, cronMode.Mode)
}

func TestNormalizeApprovalModeYAMLBooleanOff(t *testing.T) {
	mode := NormalizeApprovalMode(false)
	if mode.Mode != "off" {
		t.Fatalf("NormalizeApprovalMode(false) mode = %q, want off", mode.Mode)
	}
	if mode.Defaulted {
		t.Fatalf("NormalizeApprovalMode(false) defaulted = true, want false")
	}

	mode = NormalizeApprovalMode(true)
	if mode.Mode != "manual" {
		t.Fatalf("NormalizeApprovalMode(true) mode = %q, want manual", mode.Mode)
	}
	if mode.Defaulted {
		t.Fatalf("NormalizeApprovalMode(true) defaulted = true, want false")
	}
}

func TestNormalizeApprovalModeStringModes(t *testing.T) {
	for _, tc := range []struct {
		input string
		want  string
	}{
		{input: " manual ", want: "manual"},
		{input: "SMART", want: "smart"},
		{input: "off", want: "off"},
	} {
		t.Run(tc.input, func(t *testing.T) {
			mode := NormalizeApprovalMode(tc.input)
			if mode.Mode != tc.want {
				t.Fatalf("NormalizeApprovalMode(%q) mode = %q, want %q", tc.input, mode.Mode, tc.want)
			}
			if mode.Defaulted {
				t.Fatalf("NormalizeApprovalMode(%q) defaulted = true, want false", tc.input)
			}
		})
	}
}

func TestNormalizeApprovalModeDefaultsUnsupportedValues(t *testing.T) {
	for _, input := range []any{nil, "", "sometimes", 1, []string{"off"}, map[string]string{"mode": "off"}} {
		t.Run("default", func(t *testing.T) {
			mode := NormalizeApprovalMode(input)
			if mode.Mode != "manual" {
				t.Fatalf("NormalizeApprovalMode(%#v) mode = %q, want manual", input, mode.Mode)
			}
			if !mode.Defaulted {
				t.Fatalf("NormalizeApprovalMode(%#v) defaulted = false, want true", input)
			}
			if mode.Evidence["approval_mode_defaulted"] != "true" {
				t.Fatalf("NormalizeApprovalMode(%#v) evidence = %#v, want approval_mode_defaulted=true", input, mode.Evidence)
			}
		})
	}
}

func TestNormalizeCronApprovalModeDefaultDeny(t *testing.T) {
	for _, input := range []any{nil, "", "deny", "manual", "sometimes", true, false, 1, []string{"approve"}, map[string]string{"mode": "approve"}} {
		t.Run("default", func(t *testing.T) {
			mode := NormalizeCronApprovalMode(input)
			if mode.Mode != "deny" {
				t.Fatalf("NormalizeCronApprovalMode(%#v) mode = %q, want deny", input, mode.Mode)
			}
			if _, ok := input.(string); ok && mode.Defaulted && input == "deny" {
				t.Fatalf("NormalizeCronApprovalMode(%#v) defaulted = true, want false", input)
			}
			if mode.Evidence["cron_approval_mode"] != "deny" {
				t.Fatalf("NormalizeCronApprovalMode(%#v) evidence = %#v, want cron_approval_mode=deny", input, mode.Evidence)
			}
		})
	}
}

func TestNormalizeCronApprovalModeApproveAliases(t *testing.T) {
	for _, input := range []string{"approve", " APPROVE ", "off", "allow", "yes"} {
		t.Run(input, func(t *testing.T) {
			mode := NormalizeCronApprovalMode(input)
			if mode.Mode != "approve" {
				t.Fatalf("NormalizeCronApprovalMode(%q) mode = %q, want approve", input, mode.Mode)
			}
			if mode.Defaulted {
				t.Fatalf("NormalizeCronApprovalMode(%q) defaulted = true, want false", input)
			}
			if mode.Evidence["cron_approval_mode"] != "approve" {
				t.Fatalf("NormalizeCronApprovalMode(%q) evidence = %#v, want cron_approval_mode=approve", input, mode.Evidence)
			}
		})
	}
}

func TestCronApprovalModeApproveDoesNotBypassHardline(t *testing.T) {
	mode := NormalizeCronApprovalMode("approve")
	result := GuardCommand("rm -rf /", mode.Mode)
	if result.Approved {
